#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

# À lancer SUR L'HÔTE Linux qui portera le runner (ex. le VPS), pas sur le Mac.
# Enrôle un runner GitHub Actions auto-hébergé pour guillaume-flambard/usine,
# labellisé « usine » (le workflow cible runs-on: [self-hosted, linux, usine]).
# Idempotent : relançable sans casse. Désenrôlement : `bash ci-runner-setup.sh --remove`.

REPO_SLUG="guillaume-flambard/usine"
REPO_URL="https://github.com/${REPO_SLUG}"
RUNNER_DIR="${RUNNER_DIR:-$HOME/actions-runner-usine}"

# Récupère un token GitHub (enrôlement ou retrait) via gh si dispo, sinon le
# demande à l'humain. Un token de runner est éphémère (≈1 h) et n'est JAMAIS
# écrit sur disque ni dans git : il ne vit que dans une variable de ce process.
fetch_or_ask_token() {
  local kind="$1" var="$2" endpoint="registration-token" got=""
  [[ "$kind" == "remove" ]] && endpoint="remove-token"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    say "gh est authentifié : je peux obtenir le token pour toi."
    if confirm "Récupérer le token via gh api ?"; then
      got=$(gh api -X POST "repos/${REPO_SLUG}/actions/runners/${endpoint}" --jq .token 2>/dev/null || true)
      if [[ -n "$got" ]]; then
        printf -v "$var" '%s' "$got"
        note "token obtenu (non affiché, non stocké)."
        return
      fi
      warn "gh n'a pas pu obtenir le token (droits admin sur le dépôt requis)."
    fi
  fi
  step "Ouvre : ${REPO_URL}/settings/actions/runners/new (bouton « New self-hosted runner »)."
  step "Copie le token affiché après « --token » dans la commande ./config.sh."
  ask_secret "$var" "Colle le token :"
}

# ── Mode désenrôlement ────────────────────────────────────────────────────
if [[ "${1:-}" == "--remove" ]]; then
  TOTAL_STAGES=2
  banner "Désenrôler le runner « usine »"
  stage "Arrêter et désinstaller le service"
  if [[ -d "$RUNNER_DIR" ]]; then
    ( cd "$RUNNER_DIR" && sudo ./svc.sh stop 2>/dev/null; sudo ./svc.sh uninstall 2>/dev/null ) || warn "le service n'était peut-être pas installé."
    say "Service arrêté et désinstallé."
  else
    warn "$RUNNER_DIR est absent : rien à arrêter."
  fi
  stage "Retirer le runner de GitHub"
  REMOVE_TOKEN=""
  fetch_or_ask_token remove REMOVE_TOKEN
  if [[ -d "$RUNNER_DIR" && -n "$REMOVE_TOKEN" ]]; then
    ( cd "$RUNNER_DIR" && ./config.sh remove --token "$REMOVE_TOKEN" ) && say "Runner retiré de GitHub."
    if confirm "Supprimer aussi le dossier $RUNNER_DIR ?"; then rm -rf "$RUNNER_DIR"; say "Dossier supprimé."; fi
  fi
  finish
  exit 0
fi

banner "Runner CI auto-hébergé — usine"

# ── Stage 1 : prérequis de l'hôte ─────────────────────────────────────────
stage "Prérequis de l'hôte"
say "Ce runner remplace les minutes GitHub (bloquées côté facturation)."
say "À lancer sur l'hôte Linux qui l'hébergera (ex. le VPS), pas sur le Mac."
missing=()
for c in curl tar git; do command -v "$c" >/dev/null 2>&1 || missing+=("$c"); done
command -v sudo >/dev/null 2>&1 || missing+=("sudo")
if (( ${#missing[@]} )); then
  warn "manquants : ${missing[*]} — installe-les puis relance."
  confirm "Continuer quand même ?" || exit 1
else
  say "curl, tar, git, sudo : présents."
fi
if command -v docker >/dev/null 2>&1 && docker ps >/dev/null 2>&1; then
  say "docker : présent et accessible (le CI fait « docker build »)."
else
  warn "docker absent ou inaccessible à cet utilisateur. L'étape « Image » du CI en a besoin ; ajoute l'utilisateur au groupe docker (sudo usermod -aG docker \$USER, puis reconnecte-toi)."
fi
case "$(uname -s)" in
  Linux) : ;;
  *) warn "Hôte non-Linux détecté ($(uname -s)). Le workflow cible linux ; ce wizard suppose un hôte Linux." ;;
esac
pause "Prérequis vus. Entrée pour continuer."

# ── Stage 2 : identité du runner ──────────────────────────────────────────
stage "Dépôt et nom du runner"
say "Dépôt : $REPO_URL"
ask RUNNER_NAME "Nom du runner [défaut : $(hostname)-usine] :"
[[ -z "${RUNNER_NAME:-}" ]] && RUNNER_NAME="$(hostname)-usine"
say "Runner : $RUNNER_NAME · labels : self-hosted, linux, usine"

# ── Stage 3 : token d'enrôlement ──────────────────────────────────────────
stage "Token d'enrôlement"
say "Un token d'enrôlement éphémère (≈1 h). Il n'est ni affiché, ni stocké."
REG_TOKEN=""
fetch_or_ask_token registration REG_TOKEN
if [[ -z "$REG_TOKEN" ]]; then warn "sans token, impossible d'enrôler."; exit 1; fi

# ── Stage 4 : télécharger le runner officiel ──────────────────────────────
stage "Télécharger le runner officiel"
mkdir -p "$RUNNER_DIR"
if [[ -x "$RUNNER_DIR/config.sh" ]]; then
  say "Runner déjà téléchargé dans $RUNNER_DIR — on le réutilise."
else
  case "$(uname -m)" in
    x86_64|amd64) ARCH="x64" ;;
    aarch64|arm64) ARCH="arm64" ;;
    *) warn "architecture $(uname -m) non gérée automatiquement."; exit 1 ;;
  esac
  say "Dernière version publiée du runner…"
  VER=$(curl -fsSL https://api.github.com/repos/actions/runner/releases/latest \
        | sed -n 's/.*"tag_name": *"v\([^"]*\)".*/\1/p' | head -n1)
  [[ -z "$VER" ]] && { warn "impossible de lire la dernière version."; exit 1; }
  TARBALL="actions-runner-linux-${ARCH}-${VER}.tar.gz"
  say "Téléchargement de $TARBALL"
  curl -fsSL -o "$RUNNER_DIR/$TARBALL" \
    "https://github.com/actions/runner/releases/download/v${VER}/${TARBALL}"
  tar xzf "$RUNNER_DIR/$TARBALL" -C "$RUNNER_DIR"
  rm -f "$RUNNER_DIR/$TARBALL"
  say "Runner v$VER extrait dans $RUNNER_DIR."
fi

# ── Stage 5 : configurer + service ────────────────────────────────────────
stage "Configurer et installer le service"
say "config.sh enrôle le runner ; le service le fait survivre au reboot."
if confirm "Lancer config.sh (labels : usine) ?"; then
  ( cd "$RUNNER_DIR" && ./config.sh --url "$REPO_URL" --token "$REG_TOKEN" \
      --name "$RUNNER_NAME" --labels usine --unattended --replace )
  say "Runner configuré."
fi
if confirm "Installer et démarrer le service (sudo) ?"; then
  ( cd "$RUNNER_DIR" && sudo ./svc.sh install "$(whoami)" && sudo ./svc.sh start )
  say "Service installé et démarré."
fi

# ── Stage 6 : dépendances système de Chromium (une fois) ──────────────────
stage "Dépendances système de Chromium"
say "Le CI fait « playwright install chromium » (sans --with-deps) : les libs"
say "système s'installent ici, une fois, pour éviter un sudo dans le CI."
if command -v npx >/dev/null 2>&1; then
  if confirm "Installer les deps via « sudo npx playwright install-deps chromium » ?"; then
    sudo env "PATH=$PATH" npx --yes playwright@latest install-deps chromium || \
      warn "échec ; installe les libs Chromium à la main (doc Playwright) puis relance."
  fi
else
  warn "node/npx absent sur l'hôte. Deux options :"
  note "  - installe node puis relance ce stage, ou"
  note "  - installe les libs Chromium via apt (voir « playwright install-deps » dans la doc)."
  note "node/pnpm/uv eux-mêmes ne sont PAS requis sur l'hôte : les actions du"
  note "workflow (setup-node, pnpm/action-setup, setup-uv) les fournissent par run."
fi

# ── Stage 7 : vérification ────────────────────────────────────────────────
stage "Vérifier"
if [[ -x "$RUNNER_DIR/svc.sh" ]]; then
  ( cd "$RUNNER_DIR" && sudo ./svc.sh status ) || true
fi
say "Ouvre ${REPO_URL}/settings/actions/runners : le runner « $RUNNER_NAME »"
say "doit apparaître « Idle » (vert)."
say "Puis relance le dernier run échoué :"
note "  gh run rerun --repo $REPO_SLUG \$(gh run list --repo $REPO_SLUG -L1 --json databaseId --jq '.[0].databaseId')"
say "Désenrôler plus tard : bash scripts/ci-runner-setup.sh --remove"

finish
